use darling::{FromDeriveInput, FromVariant, ast::Fields, util::Flag};
use proc_macro2::{Span, TokenStream};
use quote::{format_ident, quote};
use syn::{Ident, spanned::Spanned};

use crate::can::{CanVariantTuple, CanVariantTupleWithIdAndType};

/// Name of the module generated by the [`CanDecode`] macro which contains the
/// CAN decode implementation of the message enum
pub const CAN_DECODE_MESSAGE_META_IDENT: &str = "__message_meta_can_decode";

#[derive(FromVariant)]
#[darling(attributes(can))]
pub struct CanDecodeVariant {
    ident: Ident,
    fields: Fields<syn::Field>,

    /// Path of a named type which should be usd
    /// as the enum variant type
    ///
    /// This is needed for unit enum variants as the message path
    /// cannot be known in those cases
    ///
    /// **Important**: This attribute is only respected when using sparse decoding and
    ///                ignored otherwise
    variant_type: Option<syn::Path>,
    /// Path of the constant holding the [`can_hal::StandardId`]
    /// of the message variant
    ///
    /// **Important**: This attribute is required when using sparse decoding and is
    ///                ignored otherwise
    variant_id: Option<syn::Path>,
}

impl CanDecodeVariant {
    fn tuple_with_id_and_type<'a>(
        &'a self,
        id_ident: &'a syn::Path,
        type_ident: &'a syn::Path,
    ) -> CanVariantTupleWithIdAndType<'a> {
        (&self.ident, id_ident, type_ident, &self.fields)
    }

    fn tuple(&self) -> CanVariantTuple<'_> {
        (&self.ident, &self.fields)
    }
}

#[derive(FromDeriveInput)]
#[darling(attributes(can), supports(enum_any), and_then = Self::ensure_exclusive_flags)]
pub struct CanDecode {
    /// Boolean flag whether the enum should be decoded in sparse mode
    ///
    /// **Important**: You cannot use sparse and dispatch at the same time
    sparse: Flag,
    /// Boolean flag whether the enum should be decoded in dispatch mode.
    /// This means that all enum variants are message enums themselves.
    ///
    /// **Important**: You cannot use dispatch and sparse at the same time
    dispatch: Flag,

    ident: Ident,
    data: darling::ast::Data<CanDecodeVariant, ()>,
}

impl CanDecode {
    fn ensure_exclusive_flags(self) -> darling::Result<Self> {
        if self.sparse.is_present() && self.dispatch.is_present() {
            Err(darling::Error::custom(
                "The `#[can(sparse)]` and `#[can(dispatch)]` attributes cannot be used at the same time!",
            ))
        } else if !self.sparse.is_present() && !self.dispatch.is_present() {
            Err(darling::Error::custom(
                "Either the `#[can(sparse)]` or `#[can(dispatch)]` attribute is needed for decoding",
            ))
        } else {
            Ok(self)
        }
    }
}

pub fn handle(can_decode: CanDecode) -> TokenStream {
    let variants = can_decode.data.take_enum().unwrap_or_default();
    let ident = can_decode.ident;

    let meta_can_decode_mod = Ident::new(CAN_DECODE_MESSAGE_META_IDENT, Span::call_site());

    let decode_impl = if can_decode.dispatch.is_present() {
        generate_can_decode_dispatch_impl(
            &ident,
            &variants
                .iter()
                .map(CanDecodeVariant::tuple)
                .collect::<Vec<_>>(),
        )
        .unwrap_or_else(syn::Error::into_compile_error)
    } else {
        let decode_variants = variants
            .iter()
            .map(|variant| {
                let variant_id_path = match &variant.variant_id {
                    Some(path) => path,
                    None => Err(syn::Error::new(variant.ident.span(), "Missing `#[can(variant_id = <ident>)]` attribute on sparse enum variant"))?,
                };

                let variant_type_path = match &variant.variant_type {
                    Some(path) => path,
                    None if variant.fields.is_newtype() => {
                        let types = variant.fields.iter().map(|field| &field.ty).collect::<Vec<_>>();
                        let variant_type = types.first().ok_or(syn::Error::new(
                            variant.ident.span(),
                            "Newtype enum variant should at least have one type",
                        ))?;

                        match variant_type {
                            syn::Type::Path(type_path) => &type_path.path,
                            ty => Err(syn::Error::new(ty.span(), "Sparse CAN decoding only supports enum variants with named types"))?,
                        }
                    },
                    None => Err(syn::Error::new(variant.ident.span(), "Cannot infer variant type from non-newtype variant. Use `#[can(decode_message = <ident>)]` to provide a type identifier."))?,
                };

                Ok(variant.tuple_with_id_and_type(variant_id_path, variant_type_path))

            })
            .collect::<syn::Result<Vec<_>>>();

        match decode_variants {
            Ok(variants) => generate_can_decode_impl(&ident, &variants),
            Err(err) => return err.into_compile_error(),
        }
    };

    quote! {
        /// generated by [`data_macros::CanDecode`] macro
        pub mod #meta_can_decode_mod {
            use super::#ident;
            use ::data_core::can_hal::{StandardId, CanDecode, codec};

            #decode_impl
        }
    }
}

/// Generate the [`can_hal::Decode`] implementation for a enum which should
/// be decoded in dispatch mode (meaning all it's variants are message enums themselves)
///
/// This function only supports enums with newtype variants
fn generate_can_decode_dispatch_impl(
    ident: &Ident,
    variants: &[CanVariantTuple<'_>],
) -> syn::Result<TokenStream> {
    let (idents, types) = variants
        .iter()
        .map(|(variant_ident, fields)| {
            if !fields.is_newtype() {
                return Err(syn::Error::new(
                    variant_ident.span(),
                    "All variants need to be newtypes when using `#[can(dispatch)]`",
                ));
            }

            let types = fields.iter().map(|field| &field.ty).collect::<Vec<_>>();

            let variant_type = types.first().ok_or(syn::Error::new(
                variant_ident.span(),
                "Newtype enum variant should at least have one type",
            ))?;

            Ok((*variant_ident, *variant_type))
        })
        .collect::<syn::Result<(Vec<_>, Vec<_>)>>()?;

    let (error_ident, decode_error) = generate_can_decode_error(ident, &idents, &types);

    let output = quote! {
        #decode_error

        impl CanDecode for #ident {
            type Error = #error_ident;

            fn from_parts(id: StandardId, data: &[u8]) -> Result<Self, Self::Error> {
                #(
                    if #types::ALL_CAN_IDS.contains(&id) {
                        return #types::from_parts(id, data)
                            .map(Self::#idents)
                            .map_err(#error_ident::#idents);
                    }
                )*
                Err(#error_ident::UnknownId(id))
            }
        }
    };
    Ok(output)
}

/// Generate the error enum used by the dispatch CAN decode
///
/// The resulting enum contains a variant for every message variant which contains the [`<can_hal::CanDecode>::Error`] type.
///
/// The function returns a tuple containing the identifier of the generated error enum and a tokenstream containing the
/// implementation of the error enum
fn generate_can_decode_error(
    ident: &Ident,
    variant_idents: &[&Ident],
    variant_types: &[&syn::Type],
) -> (Ident, TokenStream) {
    let error_ident = format_ident!("{ident}CanDecodeError");

    let mappings = variant_types
        .iter()
        .map(|variant_type| {
            quote! { <#variant_type as CanDecode>::Error }
        })
        .collect::<Vec<_>>();

    let output = quote! {
        #[derive(Debug, ::thiserror::Error)]
        pub enum #error_ident {
            #(
                #[error(transparent)] #variant_idents(#mappings),
            )*
            #[error("Unknown Id {0:#x?} to decode")]
            UnknownId(StandardId)
        }
    };

    (error_ident, output)
}

/// Generate the [`can_hal::Decode`] implementation for the message enum
///
/// This function supports enums with all kinds of variant (not just newtypes)
pub fn generate_can_decode_impl(
    ident: &Ident,
    variants: &[CanVariantTupleWithIdAndType<'_>],
) -> TokenStream
where
{
    let (id_idents, mappings) = variants.iter().map(|(variant_ident, id_ident, type_ident, fields)| {
        let variant_mapping = if fields.is_unit() {
            quote! { Ok(Self::#variant_ident) }
        } else if fields.is_struct() {
            // if the variant is a struct type, we need to assign all fields from our struct "alias" manually
            // instead of just mapping to the enum variant
            let type_idents = fields
                .iter()
                .map(|field| &field.ident)
                .collect::<Vec<_>>();

            quote! {
                codec::decode(data)
                    .map(|d: #type_ident| Self::#variant_ident { #(#type_idents: d.#type_idents),* })
            }
        } else if fields.is_newtype() {
            quote! { codec::decode(data).map(Self::#variant_ident) }
        } else {
            // if the variant is a tuple type, we need to index all fields of our tuple "alias"
            // instead of just mapping to the enum variant
            let indices = (0..fields.len()).map(syn::Index::from).collect::<Vec<_>>();
            quote! {
                codec::decode(data)
                    .map(|d: #type_ident| Self::#variant_ident (#(d.#indices),*))
            }
        };

       (*id_ident, variant_mapping)
    }).collect::<(Vec<_>, Vec<_>)>();

    quote! {
        impl CanDecode for #ident {
            type Error = codec::Error;

            fn from_parts(id: StandardId, data: &[u8]) -> Result<Self, Self::Error> {
                match id {
                    #(#id_idents => #mappings,)*
                    _ => Err(Self::Error::UnknownId),
                }
            }
        }
    }
}
